local _, ns = ...
local E = ns.DB.entries
E["npc:cyrus-therepentous"] = {t="npc",n="Cyrus Therepentous",z="burningsteppes",s="Cyrus Therepentous is a formidable black dragonspawn residing in the cavernous depths of Slither Rock in the Burning Steppes. Rather than immediately striking down intruders, he tests daring mortals to see if they possess the strength to serve the purposes of the Black dragonflight.",h="Cyrus Therepentous is a formidable black dragonspawn residing in the cavernous depths of Slither Rock in the...",sec={{t="The Master of Slither Rock",b="Secluded inside a cavern at Slither Rock, Cyrus Therepentous oversees the volcanic crags of the Burning Steppes. Like many of his kind, he views mortal travelers with immense condescension, declaring that only fools would disturb his lair. Yet beneath his ferocious exterior lies a cold calculation: rather than consuming every trespasser on sight, he offers them a lethal challenge against his minions, willing to exploit those resilient enough to survive the trials of flame.",sp=0}},faq={{q="Who is Cyrus Therepentous?",a="Cyrus Therepentous is an intelligent black dragonspawn stationed in a cave at Slither Rock in the Burning Steppes. He serves the Black dragonflight and tests mortal adventurers who dare enter his lair.",al={"cyrus therepentous","who is cyrus","slither rock dragonspawn"}},{q="Where can Cyrus Therepentous be found?",a="He resides deep inside a cave located at Slither Rock, in the northeastern region of the Burning Steppes.",al={"cyrus location","where is cyrus therepentous","cyrus cave"}},{q="Why doesn't Cyrus attack adventurers on sight?",a="While he openly considers eating trespassers, Cyrus prefers to see if mortals can be of use to him. He spares those who prove useful by pitting them against deadly trials and minions instead.",al={"why is cyrus friendly","why doesn't cyrus kill me","cyrus talk"}}},kw={"black dragonflight","burning steppes","cyrus therepentous","dragonspawn","slither rock","taste of flame"},rel={"subzone:slither-rock","zone:burningsteppes","topic:black-dragonflight","zone:searinggorge"},src={"Cyrus Therepentous"}}
E["npc:john-j-keeshan"] = {t="npc",n="John J. Keeshan",z="burningsteppes",s="Corporal John J. Keeshan is a weary human veteran of the Great Wars, having served in the Alliance military through decades of brutal conflict. After being captured by Blackrock orcs during the fighting around Stonewatch, he was dragged deep into Render's Rock as a prisoner of war.",h="Corporal John J.",sec={{t="A Lifetime of Warfare",b="Few living soldiers have seen as much combat as John J. Keeshan. A veteran of the First, Second, and Third Wars, Keeshan served across an astounding 248 consecutive tours of duty under Colonel Troteman in Bravo Company. The decades of ceaseless violence took a devastating personal toll; his wife, Jade, was slain by Blackrock orcs during the fighting, leaving him with little beyond her pendant and the hard-bitten instincts of a battlefield survivor. By the time fighting flared up in the Redridge Mountains, Keeshan was still in the thick of it, carrying the scars and memories of a lifetime spent under arms.",sp=0},{t="Captivity at Render's Rock",b="When the Blackrock clan pushed north out of the Burning Steppes into the Redridge Mountains, Keeshan stood among the defenders battling for Stonewatch Keep. Overwhelmed by the orcish assault, he was captured alive rather than slain on the field. The Blackrock invaders hauled him captive into the depths of Render's Rock, leaving the veteran imprisoned behind enemy lines until Alliance rescue parties could fight their way in to break him out.",sp=1}},faq={{q="Who is John J. Keeshan?",a="John J. Keeshan is a veteran soldier of the Alliance military who fought through the First, Second, and Third Wars as part of Bravo Company. Known as Johnny to old comrades, he is an exceptionally hardened combatant who survived hundreds of tours of duty.",al={"keeshan lore","who is keeshan","corporal keeshan"}},{q="Why is Keeshan imprisoned in Render's Rock?",a="During the battle against the Blackrock clan around Stonewatch Keep, Keeshan was overwhelmed, captured alive by the orcs, and hauled back to their encampment inside the caves of Render's Rock.",al={"why is keeshan captured","render's rock prisoner","how did keeshan get captured"}},{q="What happened to his wife?",a="Keeshan's wife, Jade, was murdered by Blackrock orcs during the wars. Following her death, Keeshan wore her pendant as a keepsake of her memory.",al={"keeshan wife","jade keeshan","keeshan pendant"}},{q="What unit did Keeshan serve with?",a="Keeshan served in Bravo Company under the command of Colonel Troteman, fighting alongside comrades such as Messner, Jorgensen, Krakauer, and Danforth across the Great Wars.",al={"bravo company","keeshan squad","troteman squad"}}},ang={["faction:Alliance"]="Keeshan represents the steep human cost of the Alliance's unending war against the Blackrock orcs, having sacrificed his youth, family, and peace of mind in service to Stormwind.",["class:Warrior"]="For warriors, Keeshan is a grim testament to sheer martial endurance, having survived hundreds of frontline engagements across three world-altering wars."},kw={"bravo company","john j keeshan","johnny keeshan","keeshan","missing in action","render's rock","stonewatch","troteman"},rel={"quest:219","subzone:render-s-rock","subzone:stonewatch","subzone:stonewatch-keep","zone:redridge","topic:third-war","topic:alliance"},src={"John J. Keeshan"}}
E["npc:marshal-maxwell"] = {t="npc",n="Marshal Maxwell",z="burningsteppes",s="Marshal Maxwell is a high-ranking officer of the Stormwind army stationed at Morgan's Vigil in the Burning Steppes. Tasked with holding the Alliance's northernmost fortified ridge above the Redridge Mountains against the Blackrock clan and the Dark Iron dwarves, he directs scouting missions into the hostile crags below. He also plays a crucial role in coordinating efforts to discover the fate of his captured comrade, Marshal Reginald Windsor.",h="Marshal Maxwell is a high-ranking officer of the Stormwind army stationed at Morgan's Vigil in the Burning...",sec={{t="A Lonely Post on the Steppes",b="Morgan's Vigil stands as a precarious outpost on the southern rim of the Burning Steppes, overlooking a wasteland choked with ash, dragonkin, and Blackrock orcs. Marshal Maxwell commands the Stormwind military detachment stationed here, providing a rare friendly sight for travelers braving the fiery crags. From this rocky bastion, he oversees defensive maneuvers to keep the hostile forces of the mountain contained before they can sweep southward into Redridge and Elwynn.",sp=0},{t="Uncovering the Truth in the Mountain",b="Beyond routine containment, Maxwell serves as the primary field liaison for operations aimed at the heart of Blackrock Spire and Blackrock Depths. When rumors surface that the captured Marshal Reginald Windsor may still live in the dungeons of the Dark Iron dwarves, it is Maxwell who receives intelligence, sifts through reports, and directs trusted champions to mount a rescue. His outpost forms the critical bridge connecting frontier reconnaissance with the political turmoil brewing inside the gates of Stormwind.",sp=1}},faq={{q="Who is Marshal Maxwell?",a="Marshal Maxwell is a commander in the Stormwind army stationed at Morgan's Vigil in the Burning Steppes. He leads the local Alliance forces keeping watch over the Blackrock orcs, Black dragons, and Dark Iron dwarves.",al={"marshal maxwell lore","who is maxwell"}},{q="Why is Marshal Maxwell stationed at Morgan's Vigil?",a="Morgan's Vigil is the Alliance's frontline encampment bordering the Burning Steppes. Maxwell is posted here to secure the mountain pass leading down into the Redridge Mountains and monitor threats pouring out of Blackrock Mountain.",al={"why is maxwell in burning steppes","morgan's vigil commander"}},{q="What is Maxwell's connection to Marshal Windsor?",a="Maxwell is the key commander assisting in the search for Marshal Reginald Windsor, who was captured and dragged into Blackrock Depths. Maxwell helps coordinate rescue efforts and routes crucial intelligence regarding Windsor back to Stormwind.",al={"maxwell and windsor","abandoned hope quest lore"}},{q="Does Marshal Maxwell help organize strikes against Blackrock Spire?",a="Yes. Maxwell directs veteran Alliance champions to dismantle the upper echelons of the Blackrock clan, issuing directives targeting General Drakkisath and his forces holding the heights of Blackrock Spire.",al={"maxwell drakkisath","maxwell's mission"}}},ang={["faction:Alliance"]="For Alliance champions braving the searing heat of the Burning Steppes, Marshal Maxwell represents the authority of Stormwind and the spearhead of the campaign against Blackrock Mountain.",["class:Warrior"]="Maxwell embodies the discipline of Stormwind's frontline military, standing tall amid volcanic ash and coordinating deep assaults behind enemy lines."},kw={"blackrock depths","burning steppes","general drakkisath","marshal maxwell","maxwell","morgans vigil","reginald windsor","stormwind army"},rel={"subzone:morgan-s-vigil","zone:burningsteppes","topic:stormwind-kingdom","topic:alliance"},src={"Marshal Maxwell"}}
E["npc:mathredis-firestar"] = {t="npc",n="Mathredis Firestar",z="burningsteppes",s="Mathredis Firestar is an eccentric blood elf mage residing at Flame Crest in the Burning Steppes. He crafts powerful enchantments known as Lesser Arcanums, drawing upon the arcane research of his deceased master. In doing so, he feeds on the residual energies unleashed during the binding process to stave off his magic addiction.",h="Mathredis Firestar is an eccentric blood elf mage residing at Flame Crest in the Burning Steppes.",sec={{t="A Master's Legacy and Magic Addiction",b="Mathredis Firestar learned the craft of making arcanums—concentrated gems of arcane empowerment—from his mentor, Telmius Dreamseeker. Telmius met a grim end within the ancient ruins of Dire Maul while trying to wrest magical secrets from the Shen'dralar. While Telmius invented these magical bindings, Mathredis lacks the mastery to produce the greatest of them. Instead, he specializes in Lesser Arcanums. For Mathredis, this work is far more than an academic exercise: like all blood elves following the fall of the Sunwell, he suffers from a gnawing hunger for arcane power. Binding materials to ancient librams releases violent discharges of magical energy, which Mathredis siphons to sustain himself.",sp=0},{t="The Art of the Arcanum",b="Adventurers who bring Mathredis the proper tomes—such as the Librams of Constitution, Resilience, Rumination, Tenacity, or Voracity—along with rare reagents will find him eager to trade his craft. The process binds volatile magical reagents directly to the text, concentrating their essence into an arcanum that can permanently enchant headwear or leg armor. So long as adventurers supply the components, Mathredis receives both payment and the ambient arcane sustenance he desperately craves.",sp=0}},faq={{q="Who is Mathredis Firestar?",a="Mathredis Firestar is a blood elf mage stationed at the neutral outpost of Flame Crest in the Burning Steppes. He is an arcanist capable of forging Lesser Arcanums to enchant armor.",al={"mathredis lore","who is mathredis firestar","firestar blood elf"}},{q="Why is Mathredis creating arcanums?",a="Following the destruction of the Sunwell, blood elves suffer from a severe magical withdrawal. Mathredis feeds on the raw, residual magical energies released during the creation and binding of arcanums to soothe his racial addiction.",al={"why make arcanums","mathredis motivation","why librams"}},{q="Who was Telmius Dreamseeker?",a="Telmius Dreamseeker was Mathredis's late master and the original inventor of arcanums. Telmius ventured to the ruins of Dire Maul to glean knowledge from the Shen'dralar, but he was murdered there before he could fully pass on all his expertise.",al={"telmius","mathredis master","who was his master"}},{q="What kinds of arcanums can Mathredis make?",a="Mathredis can forge Lesser Arcanums of Constitution, Resilience, Rumination, Tenacity, and Voracity. The most potent arcanums were known only to his master Telmius and remain beyond Mathredis's grasp.",al={"which arcanums","lesser arcanums","libram list"}}},ang={["class:Mage"]="Mages will recognize Mathredis's arcanum synthesis as a desperate, volatile method of drawing raw magical nourishment from the process of item binding."},kw={"arcanum","burning steppes","dreamseeker","firestar","flame crest","libram","mathredis","telmius"},rel={"subzone:flame-crest","zone:burningsteppes","subzone:dire-maul"},src={"Mathredis Firestar"}}
E["subzone:altar-of-storms-burning-steppes"] = {t="subzone",n="Altar of Storms (Burning Steppes)",z="burningsteppes",s="Perched in the jagged crags of the Burning Steppes, the Altar of Storms is a dark monument dedicated to fel rituals and demonic power. Blackrock clan warlocks occupy the sinister site, performing foul magic beneath the shadow of Blackrock Spire. Its dark aura draws ambitious practitioners of the shadow from across Azeroth.",h="Perched in the jagged crags of the Burning Steppes, the Altar of Storms is a dark monument dedicated to fel...",sec={{t="A Legacy of Shadow and Flame",b="Constructed during the earlier wars to channel corrupting fel magic, the Altar of Storms stands as a grim monument to dark pacts. In the Burning Steppes, hostile warlocks of the Blackrock clan control the grounds, conducting occult rituals and drawing upon demonic forces. Nearby, the encampment of the hermit Gorzeeki Wildeyes and his master Mor'zul Bloodbringer overlooks the site, where renegade practitioners study its violent energies and concoct demanding rituals for ambitious spellcasters seeking greater dark power.",sp=0}},faq={{q="What is the Altar of Storms?",a="It is a corrupted stone monument used for dark fel rituals and channeling demonic energy. Built during the wars of the Old Horde, it remains an active nexus of dark power harnessed by Blackrock warlocks.",al={"altar of storms lore","what is this altar","burning steppes altar"}},{q="Who controls the altar right now?",a="Hostile warlocks and acolytes belonging to the Blackrock orc clan occupy the grounds immediately around the altar, performing dark ceremonies and guarding their site from intruders.",al={"who is at altar of storms","altar of storms enemies","who lives here"}},{q="Who is Gorzeeki Wildeyes?",a="Gorzeeki Wildeyes is an eccentric goblin scholar of the dark arts who dwells on the hill overlooking the altar alongside his master, Mor'zul Bloodbringer. He assists powerful warlocks who are seeking to master greater demonic bindings.",al={"gorzeeki wildeyes","orc on the hill","who is gorzeeki"}}},ang={["class:Warlock"]="The Altar of Storms and its neighboring hermits, Mor'zul Bloodbringer and Gorzeeki Wildeyes, serve as crucial conduits for warlocks seeking the materials and rituals required to summon a dreaded dreadsteed.",["race:Orc"]="The altar is an uncomfortable reminder of the Old Horde's dark history, where Gul'dan's Shadow Council used similar foul shrines to infuse ogres and soldiers with dark sorcery."},kw={"altar of storms","blackrock","burning steppes","fel","gorzeeki wildeyes","mor'zul bloodbringer","warlock"},rel={"zone:burningsteppes","topic:blackrock-clan"},src={"Altar of Storms (Burning Steppes)"}}
E["subzone:blackrock-mountain"] = {t="subzone",n="Blackrock Mountain",z="burningsteppes",s="Blackrock Mountain is a massive, active volcano that towers between the Burning Steppes and the Searing Gorge. Borne from the cataclysmic summoning of Ragnaros the Firelord, its hollowed depths house ancient dwarven masonry, warring armies, and smoldering horrors.",h="Blackrock Mountain is a massive, active volcano that towers between the Burning Steppes and the Searing Gorge.",sec={{t="A Cataclysmic Origin",b="Blackrock Mountain did not exist until the climax of the War of the Three Hammers two and a half centuries ago. Facing annihilation by the united armies of Ironforge and the Wildhammer clan, Sorcerer-Thane Thaurissan reached into the depths of the earth for a weapon. His reckless spell shattered the dimensional barriers and summoned Ragnaros the Firelord into Azeroth. The resulting apocalypse tore the Redridge range apart, gouging out the Searing Gorge and Burning Steppes while thrusting a colossal volcano into the sky. Thaurissan perished in the blast, and the surviving Dark Iron clan was bound into eternal servitude to the Firelord, carving their capital, Shadowforge City, deep within the mountain's roots.",sp=0},{t="Citadel of Ash and Blood",b="During the First and Second Wars, the mountain took on a grim new significance. Guided by Cho'gall, the Shadow Council claimed the upper fortress of Blackrock Spire with the quiet acquiescence of Ragnaros's minions. Following the sack of Stormwind, Orgrim Doomhammer purged the council and claimed the spire as the fortress capital of the Horde, viewing the shared name with his own Blackrock clan as a fateful omen. Today, the mountain remains a vicious theater of war: the Dark Iron dwarves and their elemental master hold the fiery depths, while the rogue Blackrock orcs, dragonkin, and their dark masters occupy the spires above.",sp=0}},faq={{q="How was Blackrock Mountain created?",a="It was created roughly 250 years ago during the War of the Three Hammers. Desperate to defeat rival dwarven clans, Emperor Thaurissan attempted to unleash deep subterranean energies and accidentally summoned Ragnaros the Firelord, sparking an apocalyptic blast that raised the volcano.",al={"origin of blackrock mountain","who made blackrock mountain","how did the volcano form"}},{q="Why is it named Blackrock Mountain?",a="The volcano was dubbed Blackrock Mountain and Blackrock Spire centuries before the orcs ever set foot on Azeroth. When Orgrim Doomhammer arrived, he considered the shared name with the Blackrock clan to be an auspicious omen and made it his primary base of operations.",al={"blackrock name origin","named after blackrock clan"}},{q="Who controls Blackrock Mountain right now?",a="The mountain is divided in a brutal conflict. The enslaved Dark Iron dwarves control the subterranean halls of Shadowforge City in service to Ragnaros, while the remnants of the Blackrock clan and black dragonkin dominate the upper citadel of Blackrock Spire.",al={"who lives in blackrock","who rules blackrock mountain"}},{q="What zones connect through Blackrock Mountain?",a="The interior paths and chains of Blackrock Mountain serve as a direct passage between the Searing Gorge to the north and the Burning Steppes to the south.",al={"how to get through blackrock","blackrock mountain connections"}}},ang={["race:Dwarf"]="The mountain represents the darkest chapter in dwarven history: the tragic folly of the Dark Iron clan that cost them their freedom and scarred the face of the Eastern Kingdoms.",["faction:Horde"]="For the modern Horde, Blackrock Spire is a symbol of their past bondage and bloodshed under Doomhammer, now contested by rogue orcs who reject Thrall's leadership."},kw={"blackrock mountain","blackrock spire","burning steppes","doomhammer","ragnaros","searing gorge","shadowforge","thaurissan"},rel={"zone:burningsteppes","zone:searinggorge","topic:dark-iron-clan","topic:blackrock-clan","npc:orgrim-doomhammer","topic:shadow-council","topic:second-war","zone:redridge"},src={"Blackrock Mountain"}}
E["subzone:blackrock-pass"] = {t="subzone",n="Blackrock Pass",z="burningsteppes",s="Blackrock Pass is a mountain corridor connecting the northern cliffs of Redridge Mountains to the arid wastes of the Burning Steppes. Passing beneath a heavy iron gate, it marks the sudden threshold between the tranquil human heartlands and the dangerous war grounds of the Dark Iron dwarves and the Blackrock orcs. For any weary traveler journeying north on foot, it represents a harsh and perilous frontier.",h="Blackrock Pass is a mountain corridor connecting the northern cliffs of Redridge Mountains to the arid wastes...",sec={{t="A Scorched Threshold",b="Carved into the jagged spine of the mountains, Blackrock Pass serves as the overland route between Redridge Mountains and the Burning Steppes. A stout iron gate stands along the rocky boundary, demarcating the idyllic forests and lakes of the southern valleys from the volcanic ruin beyond. Crossing this line leaves behind the pastoral lands protected by Lakeshire's beleaguered militia, thrusting travelers into an open wasteland populated by fire elementals, dragonkin, and hostile orc warbands. Few make the crossing on foot unless bound for the shadow of Blackrock Mountain itself.",sp=0}},faq={{q="Where does Blackrock Pass lead?",a="Blackrock Pass connects the northern border of Redridge Mountains directly into the southern perimeter of the Burning Steppes. It is one of the direct overland gateways linking the southern Alliance territories to the foothills of Blackrock Mountain.",al={"where does blackrock pass go","blackrock pass destination","path from redridge to burning steppes"}},{q="Is it safe for travelers from Lakeshire to cross the pass?",a="No. The lands immediately north of the pass are far more lethal than the surrounding hills of Redridge. The Burning Steppes are filled with ferocious Blackrock orcs, giant fire elementals, and black whelps, making it extraordinarily hazardous for low-level adventurers and common wayfarers.",al={"can i go through blackrock pass","is blackrock pass dangerous","level requirement blackrock pass"}},{q="Who controls Blackrock Pass?",a="Neither Stormwind nor the Horde holds full control over the pass. It remains a contested, sparsely fortified chokepoint flanked by encroaching Blackrock orcs and wild beasts, monitored with deep dread by the Redridge town guards down below.",al={"who owns blackrock pass","guards at blackrock pass","faction control blackrock pass"}}},ang={["faction:Alliance"]="For the defenders of Redridge and the Kingdom of Stormwind, Blackrock Pass is a perpetual source of dread, as it offers the Blackrock orcs a straight path south into human lands."},kw={"blackrock orcs","blackrock pass","burning steppes","frontier","gate","lakeshire","redridge mountains"},rel={"zone:burningsteppes","zone:redridge","subzone:blackrock-mountain"},src={"Blackrock Pass"}}
E["subzone:blackrock-stronghold"] = {t="subzone",n="Blackrock Stronghold",z="burningsteppes",s="Blackrock Stronghold is a heavily fortified encampment carved into the crags of the northern Burning Steppes, positioned right outside the entrance to Blackrock Mountain. It serves as a major field garrison for the Blackrock orcs and their allies under the Dark Horde banner.",h="Blackrock Stronghold is a heavily fortified encampment carved into the crags of the northern Burning Steppes...",sec={{t="Garrison of the Dark Horde",b="Sprawling across the scorched foothills below Blackrock Mountain, the stronghold functions as the primary ground base for the Blackrock clan in the Burning Steppes. Unlike Thrall's Horde, these orcs cling to their warlike legacy, serving Rend Blackhand and the dragonkin who lurk above in the spire.",sp=0},{t="Front Line of Blackrock Spire",b="The stronghold serves as both an outer defense and a staging ground for attacks into the Redridge Mountains and neighboring human lands. The fortress maintains a constant watch over the southern approaches to the mountain, challenging anyone who dares traverse the blasted wastes.",sp=0}},faq={{q="What is Blackrock Stronghold?",a="It is a fortified military base situated in the northern Burning Steppes just outside Blackrock Mountain, serving as an outer garrison for the Blackrock clan of orcs.",al={"what is this place","blackrock stronghold burning steppes","what is blackrock stronghold"}},{q="Are the orcs here friendly to Thrall's Horde?",a="No. The orcs of Blackrock Stronghold belong to the Dark Horde, led by Rend Blackhand. They reject Thrall's leadership and are hostile to both the Alliance and the new Horde.",al={"is this horde","are blackrock orcs horde","friendly to horde"}}},ang={["faction:Horde"]="For Thrall's Horde, the Blackrock clan represents the shameful legacy of the Old Horde—bloodthirsty, corrupted remnants who refuse honor and peace.",["faction:Alliance"]="The stronghold is a grim reminder of the Second War, situated within striking distance of the Kingdom of Stormwind's northern borders."},kw={"blackrock clan","blackrock stronghold","burning steppes","dark horde","rend blackhand"},rel={"zone:burningsteppes","subzone:dreadmaul-rock","topic:blackrock-clan","topic:horde","topic:alliance"},src={"Blackrock Stronghold"}}
E["subzone:dreadmaul-rock"] = {t="subzone",n="Dreadmaul Rock",z="burningsteppes",s="Dreadmaul Rock is a towering crag and cave complex rising out of the fiery wastes of the Burning Steppes. It serves as the primary base of operations for the Firegut ogres, who make their home within its winding, subterranean mounds.",h="Dreadmaul Rock is a towering crag and cave complex rising out of the fiery wastes of the Burning Steppes.",sec={{t="Stronghold of the Firegut",b="Towering above the scorched plains of the Burning Steppes, Dreadmaul Rock is a massive stone formation carved out by a labyrinthine cave system. Though its name hints at a possible connection to the Dreadmaul ogres of the Blasted Lands, the rock is held firmly by the Firegut clan. These brutish ogres use the elevated paths, crags, and interior earthen mounds as a defended encampment, dominating the surrounding wasteland and menacing anyone attempting to traverse the northern slopes toward Blackrock Spire.",sp=0}},faq={{q="Who lives at Dreadmaul Rock?",a="Dreadmaul Rock is the central base for the Firegut ogres. They inhabit both the exterior cliff paths and the complex cave system buried inside the rock formation.",al={"who is at dreadmaul rock","dreadmaul rock mobs","what ogres are at dreadmaul rock"}},{q="Why is it named Dreadmaul Rock if Firegut ogres live here?",a="While the Firegut clan currently controls the peak, its name strongly suggests it may have once belonged to the Dreadmaul ogre clan, who maintain a large presence south in the Blasted Lands.",al={"why dreadmaul","dreadmaul or firegut","dreadmaul ogres connection"}},{q="What is the layout of the rock like?",a="Dreadmaul Rock consists of steep exterior ramps winding up the crag alongside an intricate interior cave network filled with ogre mounds and dwellings.",al={"dreadmaul caves","dreadmaul peak layout","navigating dreadmaul rock"}},{q="Where is Dreadmaul Rock located?",a="It is located in the Burning Steppes, standing as a prominent mountain-like formation north of the path toward the Redridge Mountains and east of Blackrock Mountain.",al={"dreadmaul rock location","where is dreadmaul rock","burning steppes ogre base"}}},ang={["faction:Alliance"]="For Alliance forces guarding the border passes from Redridge, the aggressive ogres of Dreadmaul Rock represent a constant, brutal hazard looming just across the northern ridge.",["faction:Horde"]="Horde travelers trekking across the Steppes toward Blackrock Mountain must tread carefully around Dreadmaul Rock to avoid drawing the ire of the territorial Firegut clan."},kw={"burning steppes","dreadmaul peak","dreadmaul rock","firegut ogres","ogre mound"},rel={"zone:burningsteppes","zone:redridge","topic:blackrock-clan"},src={"Dreadmaul Rock"}}
E["subzone:flame-crest"] = {t="subzone",n="Flame Crest",z="burningsteppes",s="Flame Crest is a rugged neutral outpost perched atop a rocky ledge overlooking the volcanic wastes of the Burning Steppes. Accessed only across a crude span, this precarious encampment serves as a forward staging ground against the Dark Horde entrenched in Blackrock Mountain. It provides essential aerial connections and a haven for scouts, beast collectors, and strategists.",h="Flame Crest is a rugged neutral outpost perched atop a rocky ledge overlooking the volcanic wastes of the...",sec={{t="A Precarious Perch",b="Situated high on an isolated stone outcropping, Flame Crest commands a watchful view over the scorched ash and lava plains of the Burning Steppes. Reached only by crossing a narrow, rickety wooden bridge, the outpost is naturally defensible against the prowling beasts and roaming orc warbands of the wastes. Wind riders roost along the heights, connecting the camp back across the Redridge range to Kargath, Stonard, and Thorium Point.",sp=0},{t="Shadow of Blackrock",b="Flame Crest is more than just a wind rider roost; it is a critical forward watchpoint over the Blackrock clan entrenched within Blackrock Spire. Here, deep in hostile territory, scouts gather intelligence, lay plans to break the renegade Dark Horde, and trade with eccentric loners like the pet master Kibler in his nearby cave.",sp=0}},faq={{q="What is Flame Crest?",a="Flame Crest is a neutral encampment in the Burning Steppes. Built atop a narrow rock outcropping reachable only by a crude bridge, it provides flight path connections, scouting shelter, and supplies in an otherwise deadly region.",al={"flame crest overview","what is flame crest","burning steppes horde camp"}},{q="Where does the flight master at Flame Crest fly?",a="The wind rider roost at Flame Crest maintains direct aerial routes to Kargath in the Badlands, Stonard in the Swamp of Sorrows, and the neutral staging post at Thorium Point in the Searing Gorge.",al={"flame crest fp","flame crest flight path","where does flame crest connect"}},{q="Why is the Horde maintaining an outpost in the Burning Steppes?",a="Flame Crest is a neutral camp rather than a Horde fortress, though its wind riders carry Horde travelers. Its perch offers a vantage over the Blackrock clan entrenched in Blackrock Mountain. The Dark Horde defies Warchief Thrall and poses an immediate threat to the region, making a local vantage point vital.",al={"why is horde in burning steppes","flame crest purpose","horde mission flame crest"}},{q="Who lives in the cave at Flame Crest?",a="The cave in the back of the outcropping is home to Kibler and his loquacious parrot, Opus. Kibler is an eccentric handler interested in the rare and dangerous wildlife inhabiting the surrounding wastes and Blackrock Spire.",al={"kibler cave","who is in flame crest cave","flame crest parrot"}},{q="What is Eitrigg doing at Flame Crest?",a="Eitrigg is not stationed at Flame Crest. The veteran orc serves at Warchief Thrall's side in Orgrimmar, while Flame Crest remains a neutral waystation for traders, scouts, and wind riders watching the Blackrock clan.",al={"eitrigg burning steppes","why is eitrigg at flame crest","ariok and eitrigg"}}},ang={["faction:Horde"]="Flame Crest is your sole bastion of safety in the southern Shadowforge wastes, offering flight routes and a staging area against the Blackrock clan.",["race:Orc"]="For orcs loyal to Thrall, this camp is a vantage point over the rogue Blackrock clan whose presence stains the mountain."},kw={"ariok","blackrock clan","burning steppes","eitrigg","flame crest","flight path","kibler","opus","wind rider"},rel={"zone:burningsteppes","npc:eitrigg","topic:blackrock-clan","subzone:kargath","subzone:thorium-point","subzone:stonard","topic:horde"},src={"Flame Crest"}}
E["subzone:morgan-s-vigil"] = {t="subzone",n="Morgan's Vigil",z="burningsteppes",s="Morgan's Vigil is a ruined Alliance redoubt nestled in the southeastern heights of the Burning Steppes. Once a small village, its charred homes and shattered wizard's tower now serve as an austere forward camp for scouts watching the passes to Blackrock Mountain. It remains the sole Alliance foothold in an ash-choked land dominated by Dark Iron dwarves and Blackrock orcs.",h="Morgan's Vigil is a ruined Alliance redoubt nestled in the southeastern heights of the Burning Steppes.",sec={{t="The Last Hearth in the Steppes",b="Perched upon high stone overlooking the fiery wastes, Morgan's Vigil was once a modest settlement before the horrors of the Burning Steppes overran it. Today, charred timbers and the cracked shell of a ruined mage tower stand as grim reminders of the onslaught. The remaining defenders make do beneath rough canvas tents pitched amid the soot. Despite the ruin, the camp retains a gryphon roost, offering an unbroken aerial link back across the mountains to Stormwind City. It serves as a desperately needed haven where scouts, marshals, and passing adventurers catch their breath away from the marauding warbands below.",sp=0},{t="The Long Watch",b="The outpost draws its name and purpose from the vigilance kept against the looming threat of Blackrock Mountain. With the Dark Iron clan delving deep into dark sorceries and the Blackrock orcs claiming the surrounding wastes, the camp acts as a forward staging ground. Its defenders maintain the camp's defenses, coordinate scouting runs across the ash, and secure the vital pass leading south into Redridge.",sp=0}},faq={{q="What happened to the buildings here?",a="The settlement was largely burned to the ground by hostile forces roaming the Burning Steppes, likely Blackrock orcs or Dark Iron dwarves. The stone shell of the collapsed mage tower and charred wood foundations are all that survive, forcing the current garrison to sleep under canvas tents.",al={"why is morgans vigil burned","ruins at morgans vigil","who destroyed morgans vigil"}},{q="Who is Morgan?",a="Morgan is the woman after whom the vigil is named. She is not among the defenders currently stationed at the camp.",al={"who is morgan","morgans vigil namesake","where is morgan"}},{q="Why does the Alliance maintain this camp?",a="It serves as the Alliance's only fortified vantage point in the Burning Steppes, guarding the northern pass to Redridge and keeping watch over troop movements around Blackrock Mountain while receiving swift supplies and reinforcements directly from Stormwind.",al={"why alliance here","morgans vigil purpose","why keep morgans vigil"}},{q="How can I travel to and from Morgan's Vigil?",a="The outpost maintains an Alliance gryphon master connecting directly to Stormwind City and Thorium Point across the Searing Gorge.",al={"morgans vigil flight master","how to get to morgans vigil","flight paths morgans vigil"}},{q="Is Morgan's Vigil safe from attack?",a="It is heavily guarded by Alliance sentries, but the perimeter is constantly exposed to wandering beasts, fiery elementals, and raiding orcs lurking just outside the ridge.",al={"is morgans vigil contested","can horde enter morgans vigil","safe zone"}}},ang={["faction:Alliance"]="This battered bluff is your solitary safe sanctuary in the Burning Steppes, linking directly by flight to Stormwind City while marshaling resistance against the Dark Iron and Blackrock threats.",["race:Human"]="Holding this ridge prevents the horrors spawned beneath Blackrock Mountain from pouring unchecked through the pass into the vulnerable valleys of Redridge and the heart of Stormwind."},kw={"alliance outpost","blackrock mountain","burning steppes","gryphon master","mage tower","morgans vigil","ruins"},rel={"zone:burningsteppes","subzone:blackrock-mountain","zone:stormwind","subzone:thorium-point","topic:alliance","topic:stormwind-kingdom"},src={"Morgan's Vigil"}}
E["subzone:ruins-of-thaurissan"] = {t="subzone",n="Ruins of Thaurissan",z="burningsteppes",s="The Ruins of Thaurissan are the scorched remnants of the Dark Iron clan's original surface capital in the Burning Steppes. Once a proud city nestled in the lush northern reaches of the Redridge Mountains, it was blasted to cinders during the War of the Three Hammers when Sorcerer-Thane Thaurissan inadvertently summoned the Firelord, Ragnaros.",h="The Ruins of Thaurissan are the scorched remnants of the Dark Iron clan's original surface capital in the...",sec={{t="The Fall of a Kingdom",b="Roughly two centuries ago, following their exile from Ironforge after the death of High King Modimus Anvilmar, the Dark Iron clan journeyed south and established Thaurissan City. At the climax of the War of the Three Hammers, facing total defeat by the combined forces of the Bronzebeard and Wildhammer clans, Sorcerer-Thane Thaurissan sought an ultimate weapon to turn the tide. He and seven trusted sorcerers channeled ancient magic deep beneath the earth. Instead of an obedient servant, their ritual ripped open a conduit to the Elemental Plane and summoned Ragnaros the Firelord. The cataclysmic eruption shattered the surrounding mountains, burned the verdant landscape into the ashen Burning Steppes, raised the volcano of Blackrock Mountain, and incinerated the city.",sp=0},{t="Echoes in the Ash",b="Today, shattered masonry and crumbled pillars litter the wasteland, inhabited by patrolling Dark Iron remnants and fire elementals. The Alliance, guided by Royal Historian Archesonus in Ironforge, has sent expeditions to recover ancient relics buried beneath the ash. Touching these enchanted remnants imparts vivid, terrifying memories of the cataclysm: visions of eight dwarves chanting in despair, seven corpses sprawled around a solitary kneeling thaumaturge, and a towering monolith of primal flame that claimed the souls and freedom of an entire clan.",sp=1}},faq={{q="What was this city before it was destroyed?",a="It was Thaurissan City, the proud surface capital of the Dark Iron clan. Built after their exile from Ironforge following the death of High King Modimus Anvilmar, it served as the center of their burgeoning kingdom before it was utterly obliterated.",al={"thaurissan city lore","what was thaurissan","who built thaurissan"}},{q="How was the city destroyed?",a="Desperate to win the War of the Three Hammers against the other dwarf clans, Sorcerer-Thane Thaurissan attempted to summon a powerful supernatural minion. The ritual broke the bonds holding Ragnaros beneath the earth. The Firelord's violent arrival erupted as an apocalyptic volcano, reducing the city and the surrounding lush valleys to charred ruins.",al={"how did thaurissan burn","what destroyed thaurissan","who destroyed thaurissan"}},{q="Why is the ground around the ruins an ashen wasteland?",a="The Burning Steppes were once the fertile, green northern reaches of the Redridge Mountains. The explosive cataclysm of Ragnaros's summoning ruptured the earth, raised Blackrock Mountain, and scorched the entire expanse into an arid, ash-choked wilderness.",al={"why is burning steppes ash","what happened to the land here","redridge mountains connection"}},{q="Where did the surviving Dark Iron dwarves go?",a="The survivors were enslaved by Ragnaros and his elemental minions. They retreated deep beneath Blackrock Mountain to construct Shadowforge City, abandoning their ruined capital to the wastes while toiling in service to the Firelord.",al={"where are the dark irons now","shadowforge city origin"}}},ang={["race:Dwarf"]="For dwarves of Ironforge, these ruins stand as a grim monument to the hubris of the Dark Iron clan during the War of the Three Hammers and the horrific price of calling upon elemental powers.",["faction:Alliance"]="Alliance scouts and researchers, commissioned by Royal Historian Archesonus of Ironforge, scour these smoldering foundations for relics that reveal the truth of Blackrock Mountain's master."},kw={"archesonus","burning steppes","dark iron","ragnaros","ruins of thaurissan","sorcerer-thane","thaurissan","war of the three hammers"},rel={"subzone:blackrock-mountain","topic:dark-iron-clan","topic:dark-iron-dwarf","zone:burningsteppes","npc:royal-historian-archesonus","zone:redridge","zone:ironforge","subzone:cauldron"},src={"Ruins of Thaurissan"}}
E["subzone:slither-rock"] = {t="subzone",n="Slither Rock",z="burningsteppes",s="Slither Rock is a secluded cave tucked into the far northeastern cliffs of the Burning Steppes, past the perilous Terror Wing Path. It serves as the solitary refuge of Cyrus Therepentous, a sharp-tongued black dragonspawn with his own hidden agenda.",h="Slither Rock is a secluded cave tucked into the far northeastern cliffs of the Burning Steppes, past the...",sec={{t="A Secluded Cavern",b="Tucked away in the scorched crags beyond the Terror Wing Path, Slither Rock is easy to overlook amid the fiery wastes of the Burning Steppes. Far from the roaring forges and marching orc warbands of Blackrock Spire, this remote hollow houses the solitary black dragonspawn Cyrus Therepentous. While dragonspawn are typically fiercely loyal soldiers of the Black Dragonflight, Cyrus maintains a strange, cantankerous independence here, willing to converse with mortal travelers rather than slaughtering them on sight—though never without a steady stream of insults.",sp=0}},faq={{q="Where is Slither Rock located?",a="Slither Rock is located in the far northeastern corner of the Burning Steppes. To reach it, travelers must navigate past the black dragonkin patrolling the Terror Wing Path.",al={"slither rock location","where is slither rock","find slither rock"}},{q="Who lives in Slither Rock?",a="The cave is home to Cyrus Therepentous, a solitary black dragonspawn. Unlike most of his kin who attack mortals immediately, Cyrus is willing to speak with outsiders, though he remains foul-tempered and derisive.",al={"who is in slither rock","slither rock mob","slither rock npc"}},{q="Why would an adventurer seek out this cave?",a="Adventurers brave the perilous Terror Wing Path to seek the counsel and aid of Cyrus Therepentous. Despite his abrasive attitude, the dragonspawn shares common enemies with travelers opposing the Black Dragonflight and their dark masters.",al={"why go to slither rock","slither rock quests","cyrus purpose"}}},kw={"black dragonspawn","burning steppes","cyrus therepentous","slither rock","terror wing path"},rel={"npc:cyrus-therepentous","zone:burningsteppes","subzone:terror-wing-path"},src={"Slither Rock"}}
E["subzone:terror-wing-path"] = {t="subzone",n="Terror Wing Path",z="burningsteppes",s="Terror Wing Path is a rocky canyon winding through the eastern reaches of the Burning Steppes. Infested by whelps and dragonkin of the black dragonflight, it serves as a perilous approach into the remote northeastern corner of the Steppes.",h="Terror Wing Path is a rocky canyon winding through the eastern reaches of the Burning Steppes.",sec={{t="A Dragonkin Roost",b="Carved into the craggy, ash-covered foothills of the eastern Burning Steppes, Terror Wing Path earns its name from the aerial predators and wyrmkin that claim it. Broods of the black dragonflight prowl these defiles, fiercely guarding clutches and hunting anything foolish enough to wander into their shadow. Ash and soot blanket the stone trails, making any trek beneath the canyon walls a treacherous venture.",sp=0},{t="A Perilous Passage",b="Black drakes patrol the length of the valley, and the rare magma giant Volchan is sometimes seen wandering through it. Only the most seasoned adventurers dare the journey, and seldom alone, yet it is the only way to reach the hidden cave of Slither Rock in the far northeastern corner of the Steppes.",sp=0}},faq={{q="What creatures live in Terror Wing Path?",a="The path is infested by whelps, broodlings, and larger dragonkin of the black dragonflight. They patrol the slopes aggressively and hunt ground prey across the eastern pass.",al={"terror wing mobs","what is here","dragonkin terror wing"}},{q="Where does Terror Wing Path lead?",a="It winds through the eastern side of the Burning Steppes into the region's remote northeastern corner, where the cave of Slither Rock lies hidden beyond it.",al={"where does terror wing go","terror wing path route","terror wing directions"}},{q="Why is the black dragonflight active in this canyon?",a="The black dragonflight maintains a strong grip over the Burning Steppes under Blackrock Mountain. Terror Wing Path provides nesting grounds, hunting terrain, and an eastern perimeter guarding the mountain's flanks.",al={"why are dragons here","black dragonflight terror wing","dragonflight presence"}}},ang={["class:Hunter"]="The steep terrain and flying whelps make Terror Wing Path a proving ground for marksmen tracking draconic beasts among smoke and canyon winds."},kw={"black dragonflight","burning steppes","dragonkin","redridge pass","terror wing path","whelps"},rel={"zone:burningsteppes","topic:black-dragonflight","zone:redridge"},src={"Terror Wing Path"}}
E["zone:burningsteppes"] = {t="zone",n="Burning Steppes",z="burningsteppes",s="The Burning Steppes are a scorched, volcanic wasteland flanking the southern base of Blackrock Mountain. Formed by the catastrophic summoning of Ragnaros centuries ago, this treacherous territory holds the primary overland passage between Stormwind and Khaz Modan. Today, it crawls with rogue Blackrock orcs, Firegut ogres, Dark Iron dwarves, and broodlings of the black dragonflight.",h="The Burning Steppes are a scorched, volcanic wasteland flanking the southern base of Blackrock Mountain.",sec={{t="A Cataclysmic Origin",b="Long ago, these foothills were simply the northern reaches of the Redridge Mountains. During the War of the Three Hammers, the exiled Dark Iron clan established their kingdom here, raising their capital city of Thaurissan. Facing total defeat at the hands of the Bronzebeard and Wildhammer clans, the desperate Sorcerer-Thane Thaurissan attempted to conjure elemental forces. Instead, he shattered the earth and summoned Ragnaros the Firelord into Azeroth. The violent explosion pulverized the surrounding mountains, tore open rivers of lava, and birthed the colossal volcano known as Blackrock Mountain, leaving the steppes forever charred and barren.",sp=0},{t="Echoes of the Second War",b="During the Second War, the Old Horde claimed Blackrock Spire as its foremost seat of power. At the climax of the conflict, the Grand Alliance of Lordaeron pushed deep into the Burning Steppes to lay siege to the mountain. It was at the foot of Blackrock Mountain that Warchief Orgrim Doomhammer clashed with Lord Anduin Lothar, striking down the human champion. Rather than breaking the Alliance's resolve, Lothar's death galvanized the Allied armies to rout the orcs, sealing the victory of the Second War and leaving behind an enduring valley of ash and rusted steel.",sp=0},{t="A Den of Monsters and Dragons",b="Though Thrall established a New Horde in distant Kalimdor, the Blackrock clan remaining in the steppes maintains the bloodthirsty cruelty of the Old Horde. Operating from Blackrock Stronghold, these orcs openly ally with the black dragonflight and local Firegut ogres rather than honor any truce. Meanwhile, Dark Iron dwarves and elemental servitors lurk among the fiery ruins, all while black drakes and wyrmkin prey upon unwary travelers attempting to use the thoroughfare to cross between Stormwind and the northern kingdoms.",sp=0}},faq={{q="Why is the ground charred and covered in lava?",a="Centuries ago, the Dark Iron Sorcerer-Thane Thaurissan attempted to summon an elemental minion to rescue his clan from defeat in the War of the Three Hammers. His spell mistakenly breached the Elemental Plane and summoned Ragnaros the Firelord, ripping open the earth, creating the massive Blackrock volcano, and reducing the northern Redridge Mountains to a charred wasteland.",al={"why is it burning","what happened to burning steppes","why is blackrock mountain a volcano"}},{q="Do the orcs here belong to Thrall's Horde?",a="No. The orcs in the Burning Steppes are remnants of the Blackrock clan who refuse to join Thrall's New Horde. They do not honor the armistice with the Alliance and remain dedicated to the savage, warmongering traditions of the First and Second Wars, serving Blackrock Spire and the black dragonflight.",al={"are these thralls orcs","are blackrock orcs horde","why are orcs hostile here"}},{q="Where did Anduin Lothar die?",a="Anduin Lothar was slain by Warchief Orgrim Doomhammer at the foot of Blackrock Mountain in the Burning Steppes near the end of the Second War. Lothar's demise spurred his second-in-command, Turalyon, and the Alliance forces into a furious counterattack that shattered the Horde's lines.",al={"where was lothar killed","lothar death location","orgrim doomhammer and lothar duel"}},{q="Where can the Alliance find shelter in the steppes?",a="Alliance soldiers and travelers base themselves at Morgan's Vigil, an elevated outpost in the southeastern foothills of the zone. Marshal Maxwell commands the station, watching over the northern pass and monitoring enemy troop movements around the mountain.",al={"alliance base burning steppes","where is alliance flight path","morgans vigil location"}},{q="Where does the Horde stage operations here?",a="Horde adventurers report to Flame Crest, an elevated camp located along the northeastern ridge. From here, emissaries watch the rival Blackrock clan and maintain flight connections back to the Badlands, the Swamp of Sorrows, and Searing Gorge.",al={"horde base burning steppes","flame crest","where is horde town"}},{q="What are the Ruins of Thaurissan?",a="The Ruins of Thaurissan are the remnants of the grand city built by the Dark Iron clan after their exile from Ironforge. When Thane Thaurissan summoned Ragnaros, the raw elemental blast destroyed his capital and enslaved his surviving people to the Firelord's will.",al={"thaurissan ruins","what is the destroyed dwarf city","ruins in middle of map"}}},ang={["faction:Alliance"]="The Burning Steppes are a somber, dangerous frontier where Supreme Commander Anduin Lothar fell; Marshal Maxwell at Morgan's Vigil continually seeks brave champions to counter the threats encroaching toward Redridge.",["faction:Horde"]="Thrall's New Horde watches Flame Crest with deep concern, determined to curb the dangerous, unrepentant Blackrock clan whose warmongering stains the honor of orckind.",["race:Dwarf"]="Every stone in the steppes bears witness to the Dark Iron clan's folly during the War of the Three Hammers, culminating in the shattering of their capital and the summoning of Ragnaros.",["profession:Mining"]="The volcanic landscape is rich in rare minerals, making it one of the select open-air regions on Azeroth to harvest valuable Dark Iron deposits alongside veins of rich thorium."},kw={"anduin lothar","blackrock clan","blackrock mountain","blackrock spire","burning steppes","doomhammer","flame crest","morgan's vigil","ragnaros","thaurissan"},rel={"subzone:blackrock-mountain","topic:anduin-lothar","subzone:morgan-s-vigil","subzone:flame-crest","subzone:ruins-of-thaurissan","zone:searinggorge","zone:redridge"},src={"Burning Steppes (Classic)","Burning Steppes"}}
